// When to retry a failed request, and how long to wait first.
export const MAX_ATTEMPTS = 5

const BASE_DELAY_MS = 200
const MAX_DELAY_MS = 5000
const JITTER = 0.2

export function shouldRetry(failure) {
  if (failure.status === 429 || failure.status === 503) return true
  if (failure.status === undefined && failure.code) return true
  return false
}

export function delayFor(attempt, random = Math.random) {
  const base = Math.min(BASE_DELAY_MS * 2 ** (attempt - 1), MAX_DELAY_MS)
  return base * (1 - JITTER + random() * JITTER * 2)
}

