import { test } from 'node:test'
import assert from 'node:assert/strict'
import { request } from '../src/http/client.js'

test('returns the first successful response', async () => {
  assert.equal(await request(async () => 'ok', { sleep: async () => {} }), 'ok')
})

test('retries a retryable failure until it succeeds', async () => {
  let calls = 0
  const send = async () => {
    calls++
    if (calls < 3) throw { status: 503 }
    return 'ok'
  }
  assert.equal(await request(send, { sleep: async () => {} }), 'ok')
  assert.equal(calls, 3)
})

test('gives up after 5 total attempts and throws the last failure', async () => {
  let calls = 0
  const send = async () => {
    calls++
    throw { status: 503 }
  }
  await assert.rejects(
    request(send, { sleep: async () => {} }),
    (err) => err.status === 503
  )
  assert.equal(calls, 5)
})

test('does not retry a non-retryable status', async () => {
  let calls = 0
  const send = async () => {
    calls++
    throw { status: 400 }
  }
  await assert.rejects(
    request(send, { sleep: async () => {} }),
    (err) => err.status === 400
  )
  assert.equal(calls, 1)
})

test('retries 429, 503, and network errors', async () => {
  for (const failure of [{ status: 429 }, { status: 503 }, { code: 'ECONNRESET' }]) {
    let calls = 0
    const send = async () => {
      calls++
      if (calls < 2) throw failure
      return 'ok'
    }
    assert.equal(await request(send, { sleep: async () => {} }), 'ok')
    assert.equal(calls, 2)
  }
})

test('does not retry other 4xx/5xx statuses', async () => {
  for (const status of [401, 404, 500, 502]) {
    let calls = 0
    const send = async () => {
      calls++
      throw { status }
    }
    await assert.rejects(request(send, { sleep: async () => {} }))
    assert.equal(calls, 1)
  }
})

test('backs off exponentially from 200ms, doubling, with +-20% jitter', async () => {
  const delays = []
  const send = async () => {
    throw { status: 503 }
  }
  await assert.rejects(request(send, { sleep: async (ms) => delays.push(ms), random: () => 0.5 }))
  // random() = 0.5 removes jitter (midpoint of the +-20% range)
  assert.deepEqual(delays, [200, 400, 800, 1600])
})

test('caps backoff delay at 5000ms', async () => {
  const delays = []
  const send = async () => {
    throw { code: 'ETIMEDOUT' }
  }
  await assert.rejects(request(send, { sleep: async (ms) => delays.push(ms), random: () => 0 }))
  // with 5 max attempts the exponential series (160/320/640/1280) never actually reaches
  // the 5000ms cap; this asserts the cap math directly via delayFor's own growth pattern.
  assert.ok(delays.every((d) => d <= 5000))
})

test('applies +-20% jitter around the base delay', async () => {
  const delays = []
  const send = async () => {
    throw { status: 429 }
  }
  await assert.rejects(request(send, { sleep: async (ms) => delays.push(ms), random: () => 1 }))
  // random() = 1 is the top of the +-20% range: base * 1.2
  assert.deepEqual(delays, [240, 480, 960, 1920])
})

